import Schema from "@deepseek-ai/schemastery";
//#region lib/types/config.js
/** Public polling configuration shared by the notification Host and Client halves. */
/** Validate notification polling configuration. */
const Config = Schema.object({ notificationPollIntervalMs: Schema.natural().min(1).max(2147483647).default(6e5) });
/** Bootstrap key for public notification configuration. */
const NOTIFICATIONS_CONFIG_GLOBAL = "__DSH_ACCOUNT_NOTIFICATIONS_CONFIG__";
//#endregion
//#region lib/types/index.js
/** @param ctx - Host page bootstrap collector. @param config - validated notification configuration. */
function apply(ctx, config) {
	ctx.on("webserver/index-inject", (table) => {
		table.push({
			kind: "global",
			name: NOTIFICATIONS_CONFIG_GLOBAL,
			value: config
		});
	});
}
//#endregion
export { Config, apply };
